@Service
public class FinancialAccountService {

    @Autowired
    private AccountRepository accountRepository;

    @Transactional(isolation = Isolation.SERIALIZABLE, propagation = Propagation.REQUIRED)
    public void transferFunds(Long sourceId, Long targetId, BigDecimal amount) {
        Account source = accountRepository.findById(sourceId)
            .orElseThrow(() -> new EntityNotFoundException("Source not found"));
        Account target = accountRepository.findById(targetId)
            .orElseThrow(() -> new EntityNotFoundException("Target not found"));

        if (source.getBalance().compareTo(amount) < 0) {
            throw new InsufficientFundsException("Declined");
        }

        source.setBalance(source.getBalance().subtract(amount));
        target.setBalance(target.getBalance().add(amount));

        accountRepository.save(source);
        accountRepository.save(target);
    }
}
